contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public {
        uint256 ownerBalBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();
        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            uint256 ownerBalAfter = c.balanceOf(address(this));
            uint256 totalAfter = c.totalSupply();
            assert(ownerBalAfter == ownerBalBefore - burnAmount);
            assert(totalAfter == totalBefore - burnAmount);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint256 mintedAmount) public {
        require(target != address(0));
        uint256 ownerBefore = c.balanceOf(address(this));
        uint256 targetBefore = c.balanceOf(target);
        uint256 supplyBefore = c.totalSupply();

        c.mintToken(target, mintedAmount);

        uint256 ownerAfter = c.balanceOf(address(this));
        uint256 targetAfter = c.balanceOf(target);
        uint256 supplyAfter = c.totalSupply();

        assert(targetAfter == targetBefore + mintedAmount && supplyAfter == supplyBefore + mintedAmount && ownerAfter == ownerBefore);
    }
}

