}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address freezeTarget, address thawTarget, address to, uint256 amount) public payable {
        c.freezeAccount(freezeTarget, true);
        c.freezeAccount(thawTarget, false);
        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(to);
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!reverted && to != address(0) && senderBefore >= amount) {
            assert(c.balanceOf(address(this)) == senderBefore - amount && c.balanceOf(to) == recipientBefore + amount);
        } else {
            assert(true);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));
        require(mintedAmount > 0);

        uint256 balanceBefore = c.balanceOf(target);
        uint256 totalSupplyBefore = c.totalSupply();

        c.freezeAccount(target, true);
        bool isFrozenAfterFreeze = c.frozenAccount(target);
        c.freezeAccount(target, false);
        bool isFrozenAfterThaw = c.frozenAccount(target);

        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(target);
        uint256 totalSupplyAfter = c.totalSupply();

        assert(!reverted && !isFrozenAfterFreeze && !isFrozenAfterThaw && balanceAfter == balanceBefore + mintedAmount && totalSupplyAfter == totalSupplyBefore + mintedAmount);
    }

    receive() external payable {}
}

