contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        uint256 ownerBal = c.balanceOf(address(this));
        uint256 toBal = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        if (ownerBal >= amount && !c.frozenAccount(address(this)) && !c.frozenAccount(to)) {
            try c.transfer(to, amount) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balanceOf(address(this)) == ownerBal - amount
                && c.balanceOf(to) == toBal + amount
                && c.totalSupply() == supplyBefore);
        } else {
            assert(c.balanceOf(address(this)) == ownerBal
                && c.balanceOf(to) == toBal
                && c.totalSupply() == supplyBefore);
        }
    }

    receive() external payable {}
}

